"""W21: `python -m tools.merge_main`. Merge origin/main into the current branch and repair the generated files, so two
sessions that ran in parallel never stop on a conflict that only a command can judge.

Standard library only. It runs git and the commands of tools/generated_files.json, and nothing else. The only network
use is `git fetch origin` (and whatever a regenerate command needs by itself: `npm ci` reads the npm registry or its
cache). It never pushes, never forces and never resets.

What it does, in order:
  1. Refuses a tree with any change, an unfinished merge or a detached head (exit 3, nothing changed).
  2. `git fetch origin`, then `git merge --no-commit --no-ff origin/main`.
  3. Reads tools/generated_files.json from the merged tree (a bad list is exit 64).
  4. No conflict: runs every verify, regenerates a stale file, and commits the merge and then the regenerated files as a
     separate commit named "regenerate generated files after merging main".
  5. Conflicts: when every conflicted path is on the list, takes main's version of each (a file that is only generated
     between two marker lines is merged around the block; a conflict outside the block is refused), runs the regenerate
     commands in file order, runs every verify and makes one merge commit. When any conflicted path is not on the
     list it runs `git merge --abort`, prints the paths and stops (exit 3, "Ask me first").
  6. A regenerate or verify that fails, or a file written that is not on the list, puts the tree back as it was and is
     exit 2, with the command and its last 20 lines. A missing node or npm for a ui file is exit 3, never skipped.

One line per file: kept (verify passed, nothing to do), regenerated (and what ran) or refused (and why).

Exit codes: 0 done, 2 failed (the tree is as it was), 3 ask first (the tree is as it was), 64 the list or the usage is
wrong. Never 1.
"""
import os
import shlex
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

try:
    from tools import generated_files as gf
except ImportError:  # run as a file
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
    from tools import generated_files as gf

OK, FAILED, ASK, USAGE = 0, 2, 3, 64
REGEN_COMMIT = "regenerate generated files after merging main"
PLACEHOLDER = "<<<generated block, regenerated by tools.merge_main>>>"
TAIL = 20
TIMEOUT = 1800


class Stop(Exception):
    """End the run with `code`. `restore` says whether the tree must be put back first."""

    def __init__(self, code, lines, restore=True):
        super().__init__("; ".join(lines))
        self.code, self.lines, self.restore = code, list(lines), restore


class Git:
    def __init__(self, root):
        self.root = root
        self.env = {**os.environ, "GIT_TERMINAL_PROMPT": "0", "GIT_EDITOR": "true", "LC_ALL": "C", "LANG": "C"}

    def run(self, *args, data=None):
        return subprocess.run(["git", *args], cwd=self.root, capture_output=True, env=self.env, input=data)

    def text(self, *args):
        r = self.run(*args)
        return r.returncode, r.stdout.decode("utf-8", "replace"), r.stderr.decode("utf-8", "replace")

    def names(self, *args):
        r = self.run(*args, "-z")
        if r.returncode != 0:
            raise Stop(FAILED, [f"git {' '.join(args)} failed: {r.stderr.decode('utf-8', 'replace').strip()}"])
        return [p.decode("utf-8", "surrogateescape") for p in r.stdout.split(b"\0") if p]

    def merging(self):
        return self.run("rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0


def tail(text, n=TAIL):
    lines = text.rstrip("\n").split("\n") if text.strip() else []
    return lines[-n:]


def show(cmd):
    where = f" (in {cmd['cwd']}/)" if cmd["cwd"] else ""
    return shlex.join(cmd["argv"]) + where


def resolve(argv):
    """The program to start for argv[0]: `python` is this Python; anything else must be found on PATH."""
    if argv[0] == "python":
        return sys.executable
    return shutil.which(argv[0])


def missing(cmd):
    ui = " The ui files need both node and npm." if cmd["argv"][0] in ("node", "npm") else ""
    return Stop(ASK, [f"Ask me first: {cmd['argv'][0]} is not installed or not on PATH, and {show(cmd)} needs it.{ui}",
                      "Install it and run python -m tools.merge_main again. Nothing was skipped. The tree was put back as it was."])


def run_command(root, cmd):
    """Run one command without a shell. Returns (ok, output). Raises Stop(ASK) when the program is not installed."""
    exe = resolve(cmd["argv"])
    if exe is None:
        raise missing(cmd)
    cwd = root / cmd["cwd"] if cmd["cwd"] else root
    try:
        r = subprocess.run([exe, *cmd["argv"][1:]], cwd=cwd, capture_output=True, text=True, errors="replace",
                           timeout=TIMEOUT, env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})
    except subprocess.TimeoutExpired:
        return False, f"timed out after {TIMEOUT} seconds"
    except OSError as e:
        return False, f"could not start: {e}"
    return r.returncode == 0, (r.stdout or "") + (r.stderr or "")


def command_failed(cmd, output, what):
    return Stop(FAILED, [f"{what} failed: {show(cmd)}", f"last {TAIL} lines of its output:", *tail(output),
                         "The tree was put back as it was."])


# ---------------------------------------------------------------- putting the tree back

def restore(git):
    """Back to the commit the run started on: the work tree and the index are made equal to HEAD, a merge in progress is
    aborted, and the files the run added are removed. The tree was clean when the run began, so nothing of the owner's
    is touched. No reset and no force."""
    git.run("restore", "--source=HEAD", "--staged", "--worktree", "--", ":/")
    if git.merging():
        git.run("merge", "--abort")
    for rel in git.names("ls-files", "--others", "--exclude-standard"):
        p = git.root / rel
        try:
            p.unlink()
        except OSError:
            pass


# ---------------------------------------------------------------- a file that is only generated between two markers

def _split_block(text, block):
    lines = text.split("\n")
    first = next((i for i, ln in enumerate(lines) if ln.startswith(block["begin"])), None)
    last = next((i for i in range(len(lines) - 1, -1, -1) if lines[i].startswith(block["end"])), None)
    if first is None or last is None or last < first:
        return None
    return lines[:first], lines[first:last + 1], lines[last + 1:]


def merge_around_block(git, path, block):
    """The text of `path` with the two sides merged outside the block and main's block kept, or None when that is not
    possible (a marker is missing, or the two sides changed the same lines outside the block)."""
    stages = {}
    for n in (1, 2, 3):
        r = git.run("show", f":{n}:{path}")
        stages[n] = r.stdout.decode("utf-8") if r.returncode == 0 else None
    if stages[2] is None or stages[3] is None:
        return None
    parts = {n: _split_block(stages[n], block) for n in (2, 3)}
    if stages[1] is not None:
        parts[1] = _split_block(stages[1], block)
    if parts[2] is None or parts[3] is None or (stages[1] is not None and parts[1] is None):
        return None
    base = stages[1] if stages[1] is not None else ""
    with tempfile.TemporaryDirectory(prefix="merge-main-") as tmp:
        files = {}
        for name, n in (("ours", 2), ("base", 1), ("theirs", 3)):
            if n == 1 and stages[1] is None:
                text = base
            else:
                before, _, after = parts[n]
                text = "\n".join([*before, PLACEHOLDER, *after])
            f = Path(tmp) / name
            f.write_text(text, encoding="utf-8", newline="")
            files[name] = str(f)
        r = subprocess.run(["git", "merge-file", "-p", files["ours"], files["base"], files["theirs"]], cwd=git.root,
                           capture_output=True, env=git.env)
    if r.returncode != 0:
        return None
    merged = r.stdout.decode("utf-8")
    if merged.count(PLACEHOLDER) != 1:
        return None
    return merged.replace(PLACEHOLDER, "\n".join(parts[3][1]))


# ---------------------------------------------------------------- the run

def covered(path, entries):
    return any(path == p or path.startswith(p + "/") for e in entries for p in [e["path"], *e["writes"]])


def changes(git):
    """Paths changed in the work tree since the index (what the commands wrote) and files the index does not know."""
    return sorted(set(git.names("diff", "--name-only")) | set(git.names("ls-files", "--others", "--exclude-standard")))


def start_checks(git):
    if git.run("rev-parse", "--is-inside-work-tree").returncode != 0:
        raise Stop(USAGE, ["this is not a git work tree"], restore=False)
    if git.run("symbolic-ref", "-q", "HEAD").returncode != 0:
        raise Stop(ASK, ["Ask me first: the head is detached, so there is no branch to merge into. Nothing was changed."], False)
    if git.merging():
        raise Stop(ASK, ["Ask me first: a merge is already in progress. Finish or abort it yourself. Nothing was changed."], False)
    dirty = git.names("status", "--porcelain", "--untracked-files=all", "--no-renames")
    if dirty:
        raise Stop(ASK, ["Ask me first: the tree has changes, so a merge could not be undone. Nothing was changed.",
                         *[f"  {p}" for p in dirty[:20]]], False)


def run(root):
    git = Git(root)
    start_checks(git)
    r = git.run("fetch", "origin")
    if r.returncode != 0:
        raise Stop(FAILED, ["git fetch origin failed:", *tail(r.stderr.decode("utf-8", "replace")), "Nothing was changed."], False)
    if git.run("rev-parse", "-q", "--verify", "origin/main^{commit}").returncode != 0:
        raise Stop(FAILED, ["origin/main does not exist after the fetch. Nothing was changed."], False)
    try:
        return merge_and_repair(git, root)
    except Stop as stop:
        if stop.restore:
            restore(git)
        raise
    except Exception as e:  # fail closed: the tree was clean when the run began, so it is put back
        restore(git)
        raise Stop(FAILED, [f"unexpected error: {e!r}", "The tree was put back as it was."], restore=False)


def merge_and_repair(git, root):
    r = git.run("merge", "--no-commit", "--no-ff", "origin/main")
    unmerged = git.names("diff", "--name-only", "--diff-filter=U")
    merging = git.merging()
    if r.returncode != 0 and not unmerged:
        raise Stop(FAILED, ["git merge origin/main failed:", *tail((r.stdout + r.stderr).decode("utf-8", "replace")),
                            "The tree was put back as it was."])
    lines = []
    if unmerged and gf.LIST_REL in unmerged:
        raise Stop(ASK, [*(f"refused {p}: conflict, and the list of generated files is itself in conflict" for p in unmerged),
                         "Ask me first: the merge was aborted and nothing was changed."])
    try:
        entries = gf.load(root / gf.LIST_REL)
    except gf.ListError as e:
        raise Stop(USAGE, [f"{gf.LIST_REL}: {e}", "The tree was put back as it was."])
    for e in entries:
        if not (root / e["path"]).is_file() and e["path"] not in unmerged:
            raise Stop(USAGE, [f"{gf.LIST_REL}: {e['path']} is listed but is not a file in the merged tree",
                               "The tree was put back as it was."])
    listed = {e["path"]: e for e in entries}
    refused = [p for p in unmerged if p not in listed]
    resolved = {}
    for p in unmerged:
        if p in listed:
            e = listed[p]
            if e["block"]:
                text = merge_around_block(git, p, e["block"])
                if text is None:
                    refused.append(p)
                else:
                    resolved[p] = text
            elif git.run("show", f":3:{p}").returncode != 0:
                refused.append(p)
    if refused:
        lines = []
        for p in unmerged:
            if p in refused:
                why = "not a generated file" if p not in listed else "main's version cannot be taken"
                lines.append(f"refused {p}: conflict, {why}")
        raise Stop(ASK, [*lines, "Ask me first: these paths conflict and a command cannot judge them. "
                         "The merge was aborted and nothing was changed."])
    conflicted = set(unmerged)
    for p in unmerged:
        if p in resolved:
            (root / p).write_text(resolved[p], encoding="utf-8", newline="")
        else:
            c = git.run("checkout", "--theirs", "--", p)
            if c.returncode != 0:
                raise Stop(FAILED, [f"could not take main's version of {p}", "The tree was put back as it was."])
        if git.run("add", "--", p).returncode != 0:
            raise Stop(FAILED, [f"could not stage {p}", "The tree was put back as it was."])
    outcome = repair(git, root, entries, conflicted)
    wrote = changes(git)
    stray = [p for p in wrote if not covered(p, entries)]
    if stray:
        raise Stop(FAILED, ["a command wrote a file that is not on the list:", *[f"  {p}" for p in stray],
                            "The tree was put back as it was."])
    for e in entries:
        line = outcome[e["path"]]
        if line.startswith("kept ") and e["path"] in wrote:  # written by a command that ran for another entry
            line = f"regenerated {e['path']}: written by the same command as an earlier file; ran {' then '.join(show(c) for c in e['regenerate'])}"
        lines.append(line)
    if merging and conflicted:
        if wrote and git.run("add", "--", *wrote).returncode != 0:
            raise Stop(FAILED, ["could not stage the regenerated files", "The tree was put back as it was."])
        commit(git, ["commit", "--no-edit"], "the merge commit")
        lines.append("merged origin/main with conflicts in generated files only: one merge commit")
    else:
        if merging:
            commit(git, ["commit", "--no-edit"], "the merge commit")
            lines.append("merged origin/main: merge commit made")
        else:
            lines.append("origin/main is already merged")
        if wrote:
            if git.run("add", "--", *wrote).returncode != 0:
                raise Stop(FAILED, ["could not stage the regenerated files"], restore=False)
            commit(git, ["commit", "-m", REGEN_COMMIT], "the regenerate commit")
            lines.append(f"committed {len(wrote)} regenerated file(s): {REGEN_COMMIT}")
    return lines


def commit(git, args, what):
    r = git.run(*args)
    if r.returncode != 0:
        raise Stop(FAILED, [f"{what} failed:", *tail((r.stdout + r.stderr).decode("utf-8", "replace")),
                            "The work tree was put back to the last commit."])


def repair(git, root, entries, conflicted):
    """Regenerate and verify in file order. Returns {path: the one line to print for it}."""
    done_regen = set()
    outcome = {}

    def regenerate(e):
        key = tuple((tuple(c["argv"]), c["cwd"]) for c in e["regenerate"])
        if key in done_regen:
            return
        for c in e["regenerate"]:  # every program must exist before the first one runs
            if resolve(c["argv"]) is None:
                raise missing(c)
        for c in e["regenerate"]:
            ok, out = run_command(root, c)
            if not ok:
                raise command_failed(c, out, f"regenerate for {e['path']}")
        done_regen.add(key)

    def verify(e):
        for c in e["verify"]:
            ok, out = run_command(root, c)
            if not ok:
                return c, out
        return None

    for e in entries:
        path = e["path"]
        ran = []
        if path in conflicted:
            regenerate(e)
            ran = e["regenerate"]
        bad = verify(e)
        if bad is not None and not ran:
            regenerate(e)
            ran = e["regenerate"]
            bad = verify(e)
        if bad is not None:
            raise command_failed(bad[0], bad[1], f"verify for {path}")
        if ran:
            why = "main's version taken, then regenerated" if path in conflicted else "stale, regenerated"
            outcome[path] = f"regenerated {path}: {why}; ran {' then '.join(show(c) for c in ran)}"
        else:
            outcome[path] = f"kept {path}: verify passed; ran {' then '.join(show(c) for c in e['verify'])}"
    done = set()
    for e in entries:  # a later regenerate may have changed an earlier file: verify everything once more
        for c in e["verify"]:
            key = (tuple(c["argv"]), c["cwd"])
            if key in done:
                continue
            done.add(key)
            ok, out = run_command(root, c)
            if not ok:
                raise command_failed(c, out, f"the last verify for {e['path']}")
    return outcome


def main(argv):
    if argv:
        if argv in (["-h"], ["--help"]):
            print("usage: python -m tools.merge_main   (no options)\n" + __doc__.split("Exit codes:")[0].strip())
            return OK
        print("usage: python -m tools.merge_main   (no options)", file=sys.stderr)
        return USAGE
    root = Path.cwd()
    try:
        top = subprocess.run(["git", "rev-parse", "--show-toplevel"], capture_output=True, text=True)
        if top.returncode != 0:
            print("merge_main: this is not a git work tree", file=sys.stderr)
            return USAGE
        root = Path(top.stdout.strip())
        for line in run(root):
            print(line)
        return OK
    except Stop as stop:
        out = sys.stdout if stop.code == OK else sys.stderr
        for line in stop.lines:
            print(line, file=out)
        return stop.code
    except Exception as e:  # fail closed
        print(f"merge_main: unexpected error: {e!r}", file=sys.stderr)
        return FAILED


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
